CREATE TRIGGER RefRepairCode_Version_Create
	ON RefRepairCode
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RRC_PK, 'RRC'
	FROM inserted
GO
CREATE TRIGGER RefRepairCode_Version_Update
	ON RefRepairCode
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RRC_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefRepairCode_DataChangeHistory
	ON RefRepairCode
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RRC_PK, 'RRC' FROM inserted
	UNION
	SELECT RRC_PK, 'RRC' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefRepairCode_DataProcessingResult_Delete
	ON RefRepairCode
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RRC_PK
	END
